begin
 select id into pid from public.curriculums where code='GUITAR';
 if pid is null then raise notice 'No Guitar catalog to reconcile'; return; end if;
 perform pg_advisory_xact_lock(hashtextextended('vibe:guitar-grade-catalog:20261006',0));
 lock table public.curriculum_levels,public.curriculum_subjects,public.curriculum_subject_components,public.curriculum_component_items in share row exclusive mode;
 actual := (select jsonb_build_object('code',p.code,'levels',(select jsonb_agg(jsonb_build_object('row',to_jsonb(l)-'id'-'curriculum_id'-'created_at'-'updated_at','subjects',(select coalesce(jsonb_agg(jsonb_build_object('row',to_jsonb(s)-'id'-'level_id'-'created_at'-'updated_at','components',(select coalesce(jsonb_agg(jsonb_build_object('row',to_jsonb(c)-'id'-'subject_id'-'created_at'-'updated_at','items',(select coalesce(jsonb_agg(to_jsonb(i)-'id'-'component_id'-'created_at'-'updated_at' order by i.sort_order),'[]') from curriculum_component_items i where i.component_id=c.id)) order by c.sort_order),'[]') from curriculum_subject_components c where c.subject_id=s.id and c.status='ACTIVE')) order by s.sort_order),'[]') from curriculum_subjects s where s.level_id=l.id and s.code in ('REPERTOIRE','TECHNIQUE_FOUNDATION','SIGHTREADING','AURAL','ENSEMBLE','MUSIC_HISTORY','MEDIA_PRODUCT'))) order by l.sequence_no) from curriculum_levels l where l.curriculum_id=p.id and l.code like 'GRADE_%')) from curriculums p where p.code='GUITAR');
