 actual := (select jsonb_build_object('code',p.code,'levels',(select jsonb_agg(jsonb_build_object('row',to_jsonb(l)-'id'-'curriculum_id'-'created_at'-'updated_at','subjects',(select coalesce(jsonb_agg(jsonb_build_object('row',to_jsonb(s)-'id'-'level_id'-'created_at'-'updated_at','components',(select coalesce(jsonb_agg(jsonb_build_object('row',to_jsonb(c)-'id'-'subject_id'-'created_at'-'updated_at','items',(select coalesce(jsonb_agg(to_jsonb(i)-'id'-'component_id'-'created_at'-'updated_at' order by i.sort_order),'[]') from curriculum_component_items i where i.component_id=c.id)) order by c.sort_order),'[]') from curriculum_subject_components c where c.subject_id=s.id)) order by s.sort_order),'[]') from curriculum_subjects s where s.level_id=l.id)) order by l.sequence_no) from curriculum_levels l where l.curriculum_id=p.id and l.code like 'GRADE_%')) from curriculums p where p.code='GUITAR');
 if actual is distinct from expected_legacy then raise exception 'GUITAR_CATALOG_DRIFT: legacy catalog differs from the reviewed source'; end if;
 if exists(select 1 from student_level_progress lp join curriculum_levels cl on cl.id=lp.level_id where cl.curriculum_id=pid and cl.code like 'GRADE_%') then
  raise exception 'GUITAR_PROGRESS_RECONCILIATION_REQUIRED: do not overwrite existing assessed history';
 end if;
 for lv in select value from jsonb_array_elements(desired->'levels') loop
  select id into strict lid from curriculum_levels where curriculum_id=pid and code=lv->'row'->>'code';
  update curriculum_levels set name=lv->'row'->>'name',status=lv->'row'->>'status',level_type=lv->'row'->>'level_type',level_number=(lv->'row'->>'level_number')::int,completion_rule=lv->'row'->>'completion_rule' where id=lid;
  for sv in select value from jsonb_array_elements(lv->'subjects') loop
   oldcode:=coalesce(aliases->>(sv->'row'->>'code'),sv->'row'->>'code');
   select id into sid from curriculum_subjects where level_id=lid and code=oldcode;
   if sid is null then raise exception 'GUITAR_SUBJECT_IDENTITY_MISSING: % / %',lv->'row'->>'code',oldcode;end if;
   update curriculum_subjects set code=sv->'row'->>'code',name=sv->'row'->>'name',family_code=sv->'row'->>'family_code',subject_level=(sv->'row'->>'subject_level')::int,sort_order=(sv->'row'->>'sort_order')::int,status=sv->'row'->>'status',is_required=(sv->'row'->>'is_required')::boolean,completion_rule=sv->'row'->>'completion_rule' where id=sid;
   update curriculum_subject_components set status='INACTIVE' where subject_id=sid and status<>'INACTIVE';
   for cv in select value from jsonb_array_elements(sv->'components') loop
    insert into curriculum_subject_components(subject_id,code,name,sort_order,status,is_required,completion_rule) values(sid,cv->'row'->>'code',cv->'row'->>'name',(cv->'row'->>'sort_order')::int,cv->'row'->>'status',(cv->'row'->>'is_required')::boolean,cv->'row'->>'completion_rule') returning id into cid;
    for iv in select value from jsonb_array_elements(cv->'items') loop
     insert into curriculum_component_items(component_id,code,name,sort_order,status,is_required) values(cid,iv->>'code',iv->>'name',(iv->>'sort_order')::int,iv->>'status',(iv->>'is_required')::boolean);
    end loop;
   end loop;
  end loop;
  update curriculum_subjects set status='INACTIVE' where level_id=lid and code not in(select value->'row'->>'code' from jsonb_array_elements(lv->'subjects'));
 end loop;
 -- The local catalog ends at Grade 8. Retain the empty legacy Diploma ID, archived only if unreferenced.
 select id into d from curriculum_levels where curriculum_id=pid and code='DIPLOMA';
 if d is not null then
  refs:=0;
  for ref in select conrelid::regclass as rel,a.attname as col from pg_constraint con join pg_attribute a on a.attrelid=con.conrelid and a.attnum=con.conkey[1] where con.contype='f' and con.confrelid='curriculum_levels'::regclass and cardinality(con.conkey)=1 loop
   execute format('select count(*) from %s where %I=$1',ref.rel,ref.col) into refs using d;
   exit when refs>0;
  end loop;
  if refs=0 then update curriculum_levels set status='INACTIVE' where id=d;end if;
 end if;
 actual := (select jsonb_build_object('code',p.code,'levels',(select jsonb_agg(jsonb_build_object('row',to_jsonb(l)-'id'-'curriculum_id'-'created_at'-'updated_at','subjects',(select coalesce(jsonb_agg(jsonb_build_object('row',to_jsonb(s)-'id'-'level_id'-'created_at'-'updated_at','components',(select coalesce(jsonb_agg(jsonb_build_object('row',to_jsonb(c)-'id'-'subject_id'-'created_at'-'updated_at','items',(select coalesce(jsonb_agg(to_jsonb(i)-'id'-'component_id'-'created_at'-'updated_at' order by i.sort_order),'[]') from curriculum_component_items i where i.component_id=c.id)) order by c.sort_order),'[]') from curriculum_subject_components c where c.subject_id=s.id and c.status='ACTIVE')) order by s.sort_order),'[]') from curriculum_subjects s where s.level_id=l.id and s.code in ('REPERTOIRE','TECHNIQUE_FOUNDATION','SIGHTREADING','AURAL','ENSEMBLE','MUSIC_HISTORY','MEDIA_PRODUCT'))) order by l.sequence_no) from curriculum_levels l where l.curriculum_id=p.id and l.code like 'GRADE_%')) from curriculums p where p.code='GUITAR');
 if actual is distinct from desired then raise exception 'GUITAR_CATALOG_POSTCONDITION_FAILED';end if;
 if (select count(*) from curriculum_component_items i join curriculum_subject_components c on c.id=i.component_id join curriculum_subjects s on s.id=c.subject_id join curriculum_levels l on l.id=s.level_id where l.curriculum_id=pid and l.code like 'GRADE_%' and s.status='ACTIVE' and c.status='ACTIVE' and i.status='ACTIVE')<>320 then raise exception 'GUITAR_LESSON_COUNT_MISMATCH';end if;
end $guitar$;
